-- Import
begin;
do $cap$ begin if pg_database_size(current_database()) > 113970579 then raise exception 'Pretoria East expansion reached its 100 MB growth cap'; end if; end $cap$;
do $before$ begin
  perform 1 from public.places where id in ('pna-castle-gate','pna-the-grove','pna-woodlands') order by id for update;
  if exists (select 1 from public.places where id in ('pna-menlyn','pna-hazeldean') or (group_id='pna' and region_id in ('menlyn','hazeldean','silver-lakes'))) then raise exception 'Batch 12 new branch already exists; recheck'; end if;
  if not exists (select 1 from public.place_groups where id='pna' and is_active and category_id='shops') then raise exception 'Batch 12 PNA group mismatch'; end if;
  if not exists (select 1 from public.places p where p.id='pna-castle-gate' and p.is_active and md5(to_jsonb(p)::text)='0e47c6882974b9a2d90f662a2e2ad65f') then raise exception 'Batch 12 prior branch changed: pna-castle-gate'; end if;
  if (select jsonb_agg(to_jsonb(h) order by sort_order) from public.place_hours h where h.place_id='pna-castle-gate' and hours_type='opening') is distinct from null::jsonb then raise exception 'Batch 12 prior hours changed: pna-castle-gate'; end if;
  if not exists (select 1 from public.places p where p.id='pna-the-grove' and p.is_active and md5(to_jsonb(p)::text)='cad5fe1a426a265d362b4ff32162e9f4') then raise exception 'Batch 12 prior branch changed: pna-the-grove'; end if;
  if (select jsonb_agg(to_jsonb(h) order by sort_order) from public.place_hours h where h.place_id='pna-the-grove' and hours_type='opening') is distinct from null::jsonb then raise exception 'Batch 12 prior hours changed: pna-the-grove'; end if;
