  if (select jsonb_agg(to_jsonb(h) order by sort_order) from public.place_hours h where h.place_id='pna-woodlands' and hours_type='opening') is distinct from '[{"id":"3b53578d-ac70-4228-bfd9-743532b93e35","place_id":"pna-woodlands","is_closed":false,"open_time":"09:00:00","close_time":"19:00:00","hours_type":"opening","sort_order":1,"source_url":"https://woodlandsboulevard.co.za/shop/pna","day_of_week":"Mon","source_checked_at":"2026-10-17"},{"id":"b5aa3af0-89f3-463d-b23f-c042aa513350","place_id":"pna-woodlands","is_closed":false,"open_time":"09:00:00","close_time":"19:00:00","hours_type":"opening","sort_order":2,"source_url":"https://woodlandsboulevard.co.za/shop/pna","day_of_week":"Tue","source_checked_at":"2026-10-17"},{"id":"b22d6043-a579-4e3a-bd63-07fd19adadf7","place_id":"pna-woodlands","is_closed":false,"open_time":"09:00:00","close_time":"19:00:00","hours_type":"opening","sort_order":3,"source_url":"https://woodlandsboulevard.co.za/shop/pna","day_of_week":"Wed","source_checked_at":"2026-10-17"},{"id":"1fdb6722-3b7a-4054-82f5-07fac2415435","place_id":"pna-woodlands","is_closed":false,"open_time":"09:00:00","close_time":"19:00:00","hours_type":"opening","sort_order":4,"source_url":"https://woodlandsboulevard.co.za/shop/pna","day_of_week":"Thu","source_checked_at":"2026-10-17"},{"id":"22720903-b4eb-4a74-b01a-4bb1ba2671d8","place_id":"pna-woodlands","is_closed":false,"open_time":"09:00:00","close_time":"19:00:00","hours_type":"opening","sort_order":5,"source_url":"https://woodlandsboulevard.co.za/shop/pna","day_of_week":"Fri","source_checked_at":"2026-10-17"},{"id":"c3224c2b-4d8d-4ff2-a7cb-e6e906735b22","place_id":"pna-woodlands","is_closed":false,"open_time":"09:00:00","close_time":"19:00:00","hours_type":"opening","sort_order":6,"source_url":"https://woodlandsboulevard.co.za/shop/pna","day_of_week":"Sat","source_checked_at":"2026-10-17"},{"id":"b71a3cbf-bc5a-41ee-a4ec-c00cb48dcfe2","place_id":"pna-woodlands","is_closed":false,"open_time":"09:00:00","close_time":"17:00:00","hours_type":"opening","sort_order":7,"source_url":"https://woodlandsboulevard.co.za/shop/pna","day_of_week":"Sun","source_checked_at":"2026-10-17"}]'::jsonb then raise exception 'Batch 12 prior hours changed: pna-woodlands'; end if;
end $before$;
do $after$ begin
  if (select count(*) from public.places where id in ('pna-menlyn','pna-hazeldean') and not is_active and group_id='pna' and source_checked_at='2026-10-18') <> 2 then raise exception 'Batch 12 inactive branch check failed'; end if;
  if (select count(*) from public.place_hours where place_id in ('pna-castle-gate','pna-the-grove','pna-woodlands','pna-menlyn','pna-hazeldean') and hours_type='opening' and source_url='https://www.pna.co.za/pna-locations/' and source_checked_at='2026-10-18') <> 35 then raise exception 'Batch 12 requires 35 sourced opening days'; end if;
  if not exists (select 1 from public.live_statuses s where s.place_id='pna-castle-gate' and md5(to_jsonb(s)::text)='dfdcc3d01fbb8bca66bee8470f74883e') then raise exception 'Batch 12 status changed: pna-castle-gate'; end if;
  if not exists (select 1 from public.live_statuses s where s.place_id='pna-the-grove' and md5(to_jsonb(s)::text)='d607765081e91d5e1875bb1ed67c7f61') then raise exception 'Batch 12 status changed: pna-the-grove'; end if;
  if not exists (select 1 from public.live_statuses s where s.place_id='pna-woodlands' and md5(to_jsonb(s)::text)='14d35a8ec0ce29f67fc4d00148639523') then raise exception 'Batch 12 status changed: pna-woodlands'; end if;
end $after$;
do $cap$ begin if pg_database_size(current_database()) > 113970579 then raise exception 'Pretoria East expansion reached its 100 MB growth cap'; end if; end $cap$;
commit;
